<script setup lang="ts">
import { computed, onMounted, onUnmounted, shallowRef, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import AppIcon from "./AppIcon.vue";
import AdminDialog from "./AdminDialog.vue";
import { confirmation, resolveConfirmation } from "../composables/useConfirm";
import { allowContextChange } from "../composables/useUnsavedChanges";
import { dispatchGroupChanged, dispatchRefreshCurrent } from "../composables/useRefreshEvents";
import { routes } from "../router";
import { workspaces } from "../workspaces";
import { api, queryString, type GlobalSearchResult } from "../services/api";
import { useAppStore } from "../stores/app";
const app = useAppStore(), route = useRoute(), router = useRouter();
const mobileNavOpen = shallowRef(false), collapsed = shallowRef(localStorage.getItem("ubot-nav-collapsed") === "true");
const themeOpen = shallowRef(false), userOpen = shallowRef(false), commandOpen = shallowRef(false);
const commandQuery = shallowRef(""), searchResults = shallowRef<GlobalSearchResult[]>([]), searchLoading = shallowRef(false);
const isLogin = computed(() => route.name === "login");
const pages = computed(() => routes.filter(item => item.name && item.name !== "login" && item.meta.navigation !== false && (!item.meta.superOnly || app.role === "super_admin")));
const navigation = computed(() => workspaces.map(workspace => ({ ...workspace, items: pages.value.filter(page => workspace.pages.includes(String(page.name))) })).filter(workspace => workspace.items.length));
const workspace = computed(() => navigation.value.find(item => item.id === route.meta.workspace));
const title = computed(() => route.name === "settings" ? route.query.tab === "runtime" ? "运行策略" : "模型配置" : String(route.meta.title || "UBot"));
const roleLabel = computed(() => app.role === "super_admin" ? "超级管理员" : "群管理员");
const tabs = computed(() => (workspace.value?.items || []).flatMap(item => item.name === "settings" ? [{ path: "/settings", title: "模型", query: { tab: "models" } }, { path: "/settings", title: "运行策略", query: { tab: "runtime" } }] : [{ path: item.path, title: String(item.meta.title), query: {} as Record<string,string> }]));
const matchingPages = computed(() => pages.value.filter(item => `${item.meta.title} ${item.meta.subtitle}`.toLowerCase().includes(commandQuery.value.trim().toLowerCase())));
function tabActive(tab: typeof tabs.value[number]) { return route.path === tab.path && (!tab.query.tab || (route.query.tab || "models") === tab.query.tab); }
function closeFloating() { themeOpen.value = false; userOpen.value = false; }
async function go(path: string, groupId?: string) { commandOpen.value = false; mobileNavOpen.value = false; closeFloating(); await router.push({ path, query: { ...(groupId || app.groupId ? { group: groupId || app.groupId } : {}) } }); }
async function logout() { if (!await allowContextChange()) return; try { await app.logout(); } catch(error) { app.showToast((error as Error).message,"error"); } }
function changeGroup(event: Event) { const groupId = (event.target as HTMLSelectElement).value; void router.replace({ query: { ...route.query, group: groupId || undefined } }); }
function themeLabel(mode: string) { return ({ light:"浅色", dark:"深色", system:"跟随系统" } as Record<string,string>)[mode] || mode; }
function keydown(event: KeyboardEvent) { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); commandOpen.value = true; closeFloating(); } if (event.key === "Escape") { closeFloating(); mobileNavOpen.value = false; } }
onMounted(async () => { app.applyTheme(); window.addEventListener("keydown",keydown); if (!isLogin.value) { await app.loadSession(); await app.loadGroups(); const initial = String(route.query.group || ""); if (app.groups.some(group => group.groupId === initial)) app.groupId = initial; } });
onUnmounted(() => window.removeEventListener("keydown",keydown));
watch(collapsed,value => localStorage.setItem("ubot-nav-collapsed",String(value)));
watch(() => app.groupId, () => { dispatchGroupChanged(); if (!isLogin.value && app.groupId && route.query.group !== app.groupId) void router.replace({ query: { ...route.query, group: app.groupId } }); });
watch(() => route.query.group, value => { if (value && app.groups.some(group => group.groupId === value) && app.groupId !== value) app.groupId = String(value); });
watch(() => route.fullPath,() => { mobileNavOpen.value = false; closeFloating(); });
watch(commandQuery,async (value,_,cleanup) => { const q = value.trim(); searchResults.value = []; if (!q) return; const controller = new AbortController(); cleanup(() => controller.abort()); searchLoading.value = true; try { const data = await api<{results:GlobalSearchResult[]}>(`/api/search${queryString({q,groupId:app.groupId})}`,{signal:controller.signal}); searchResults.value = data.results; } catch(error) { if (!controller.signal.aborted) app.showToast((error as Error).message,"error"); } finally { if (!controller.signal.aborted) searchLoading.value = false; } });
</script>
<template>
  <RouterView v-if="isLogin" />
  <div v-else class="app-shell" :class="{ 'nav-collapsed': collapsed }">
    <a href="#page-content" class="skip-link">跳到页面内容</a>
    <aside class="sidebar" :class="{open:mobileNavOpen}" aria-label="工作区导航">
      <a class="brand" href="/" @click.prevent="go('/')"><span class="brand-mark">UB</span><div class="brand-copy"><strong>UBot</strong><small>群聊运营控制台</small></div></a>
      <div class="nav-caption">工作区</div>
      <nav class="nav-list"><RouterLink v-for="item in navigation" :key="item.id" :to="{path:item.items[0].path,query:app.groupId ? {group:app.groupId} : {}}" class="nav-item" :class="{active:workspace?.id===item.id}" :title="item.title" @click="mobileNavOpen=false"><AppIcon :name="item.icon" :size="19"/><span>{{item.title}}</span></RouterLink></nav>
      <footer class="sidebar-footer"><div class="side-account"><span class="avatar">{{app.username.slice(0,1).toUpperCase()}}</span><div><strong>{{app.username}}</strong><small>{{roleLabel}}</small></div></div><button class="collapse-btn" type="button" :aria-label="collapsed ? '展开侧栏' : '折叠侧栏'" @click="collapsed=!collapsed">{{collapsed ? '›' : '‹'}}<span>折叠侧栏</span></button></footer>
    </aside>
    <button v-if="mobileNavOpen" class="nav-backdrop" aria-label="关闭导航" @click="mobileNavOpen=false" />
    <main class="main-area">
      <header class="topbar"><button class="mobile-menu-btn icon-btn" type="button" :aria-expanded="mobileNavOpen" aria-label="打开导航" @click="mobileNavOpen=!mobileNavOpen">☰</button><div class="breadcrumb"><span>控制台</span><span>/</span><strong>{{workspace?.title}}</strong></div><div class="top-actions"><select :value="app.groupId" class="group-select select" aria-label="当前群" @change="changeGroup"><option v-for="group in app.groups" :key="group.groupId" :value="group.groupId">{{group.groupName || group.groupId}}</option><option v-if="!app.groups.length" value="">暂无授权群</option></select><button class="search-trigger" aria-label="搜索页面、成员、记忆" @click="commandOpen=true"><AppIcon name="search"/><span>搜索…</span><kbd>Ctrl K</kbd></button><button class="icon-btn" type="button" title="刷新当前页" aria-label="刷新当前页" @click="dispatchRefreshCurrent"><AppIcon name="refresh"/></button><div class="popover-wrap"><button class="icon-btn" type="button" title="切换主题" aria-label="切换主题" @click="themeOpen=!themeOpen;userOpen=false"><AppIcon name="theme"/></button><div v-if="themeOpen" class="top-popover"><strong>显示主题</strong><button v-for="mode in (['light','dark','system'] as const)" :key="mode" :data-smoke="'theme-'+mode" :class="{active:app.themeMode===mode}" @click="app.applyTheme(mode);themeOpen=false">{{themeLabel(mode)}}</button></div></div><div class="popover-wrap"><button class="avatar user-chip" aria-label="账号菜单" @click="userOpen=!userOpen;themeOpen=false">{{app.username.slice(0,1).toUpperCase()}}</button><div v-if="userOpen" class="top-popover"><strong>{{app.username}}</strong><small class="muted">{{roleLabel}}</small><button @click="go('/security')">账号与安全</button><button data-smoke="logout" @click="logout">退出登录</button></div></div></div></header>
      <button v-if="themeOpen || userOpen" class="popover-backdrop" aria-label="关闭菜单" @click="closeFloating"/>
      <div class="workspace-tabs" aria-label="工作区页面"><RouterLink v-for="tab in tabs" :key="tab.title" :to="{path:tab.path,query:{...tab.query,...(app.groupId?{group:app.groupId}:{})}}" :class="{active:tabActive(tab)}">{{tab.title}}</RouterLink></div>
      <section id="page-content" class="content-scroll" tabindex="-1"><RouterView/></section>
    </main>
  </div>
  <div v-if="app.toast.visible" class="toast" :class="app.toast.type" role="status">{{app.toast.message}}</div>
  <AdminDialog v-if="commandOpen" title="搜索控制台" @close="commandOpen=false"><input v-model="commandQuery" class="input command-input" placeholder="页面、成员、记忆、FAQ…" aria-label="搜索关键词" autofocus/><div class="command-results"><small class="muted" v-if="searchLoading">正在搜索…</small><button v-for="item in searchResults" :key="item.path+item.title" @click="go(item.path,item.groupId)"><strong>{{item.title}}</strong><small>{{item.subtitle}}</small></button><span v-if="commandQuery && !searchLoading && !searchResults.length" class="muted">没有匹配的业务记录</span><p class="eyebrow">页面</p><button v-for="item in matchingPages" :key="item.path" @click="go(item.path)"><strong>{{item.meta.title}}</strong><small>{{item.meta.subtitle}}</small></button></div></AdminDialog>
  <AdminDialog v-if="confirmation" :title="confirmation.title" @close="resolveConfirmation(false)"><p class="confirm-message">{{confirmation.message}}</p><template #footer><button class="ghost-btn" type="button" @click="resolveConfirmation(false)">取消</button><button class="btn" :class="{danger:confirmation.danger}" type="button" @click="resolveConfirmation(true)">{{confirmation.confirmText || '确定'}}</button></template></AdminDialog>
</template>
<style scoped>
.app-shell{display:grid;grid-template-columns:var(--sidebar-width) minmax(0,1fr);min-height:100dvh}.nav-collapsed{--sidebar-width:76px}.sidebar{height:100dvh;position:sticky;top:0;display:flex;flex-direction:column;background:var(--surface);border-right:1px solid var(--line);padding:26px 14px 14px;z-index:45}.brand{display:flex;gap:12px;align-items:center;padding:0 10px 28px}.brand-mark{background:var(--accent);color:var(--surface);display:grid;place-items:center;width:34px;height:34px;border-radius:9px;font-weight:750;font-size:12px;flex-shrink:0}.brand-copy strong{display:block;font-size:20px;letter-spacing:-.7px}.brand-copy small{display:block;color:var(--muted);font-size:11px;margin-top:2px}.nav-caption{font-size:11px;color:var(--subtle);padding:8px 14px 12px}.nav-list{display:grid;gap:6px}.nav-item{display:flex;align-items:center;gap:12px;min-height:46px;padding:0 14px;border-radius:7px;color:var(--muted);position:relative}.nav-item:hover{background:var(--surface-soft);color:var(--text)}.nav-item.active{color:var(--accent-strong);background:var(--accent-soft);font-weight:650}.nav-item.active:before{content:'';position:absolute;left:0;top:12px;bottom:12px;width:3px;border-radius:2px;background:var(--accent)}.sidebar-footer{margin-top:auto;border-top:1px solid var(--line);padding-top:18px}.side-account{display:flex;align-items:center;gap:10px;padding:0 8px}.side-account strong{display:block;font-size:12px}.side-account small{display:block;color:var(--muted);font-size:11px;margin-top:4px}.avatar{width:32px;height:32px;display:grid;place-items:center;border-radius:50%;background:var(--accent-soft);color:var(--accent-strong);font-weight:650;flex-shrink:0}.collapse-btn{display:flex;align-items:center;gap:14px;color:var(--muted);padding:16px 14px 4px;font-size:22px;width:100%}.collapse-btn span{font-size:12px}.nav-collapsed .brand-copy,.nav-collapsed .nav-caption,.nav-collapsed .nav-item span,.nav-collapsed .side-account div,.nav-collapsed .collapse-btn span{display:none}.nav-collapsed .brand{padding-left:6px}.nav-collapsed .nav-item{padding:0;justify-content:center}.nav-collapsed .side-account{padding:0 7px}.main-area{min-width:0}.topbar{display:flex;align-items:center;gap:16px;justify-content:space-between;min-height:64px;padding:0 28px;background:var(--surface);border-bottom:1px solid var(--line);position:sticky;top:0;z-index:32}.breadcrumb{display:flex;align-items:center;gap:12px;font-size:12px;color:var(--muted);white-space:nowrap}.breadcrumb strong{font-weight:550;color:var(--text)}.top-actions{display:flex;align-items:center;gap:10px}.group-select{max-width:210px;min-width:160px}.search-trigger{display:flex;align-items:center;gap:8px;color:var(--muted);border:1px solid var(--line);border-radius:7px;height:36px;padding:0 10px;width:180px;text-align:left}.search-trigger kbd{margin-left:auto;font-size:10px;color:var(--subtle)}.popover-wrap{position:relative}.top-popover{position:absolute;top:46px;right:0;background:var(--surface);border:1px solid var(--line);border-radius:8px;padding:12px;box-shadow:var(--shadow-lg);display:grid;gap:6px;width:210px;z-index:50}.top-popover button{padding:9px 12px;border-radius:5px;color:var(--text);text-align:left}.top-popover button:hover,.top-popover button.active{background:var(--accent-soft);color:var(--accent-strong)}.popover-backdrop{position:fixed;inset:0;z-index:31;cursor:default}.workspace-tabs{display:flex;gap:28px;padding:0 28px;background:var(--surface);border-bottom:1px solid var(--line);overflow:auto;white-space:nowrap}.workspace-tabs a{padding:16px 0 13px;border-bottom:2px solid transparent;font-size:13px;color:var(--muted)}.workspace-tabs a.active{border-color:var(--accent);color:var(--accent-strong);font-weight:650}.content-scroll{padding:24px 28px 36px;max-width:1600px;margin:auto}.page-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:24px}.page-heading h1{font-size:27px;letter-spacing:-.8px;font-weight:650;margin:5px 0 7px;color:var(--text-strong)}.page-heading p:not(.eyebrow){font-size:13px;color:var(--muted);margin:0;line-height:1.6}.eyebrow{font-size:11px;color:var(--subtle);margin:0;font-weight:550}.context-label{font-size:12px;text-align:right;color:var(--muted)}.context-label small{display:block;font-family:var(--font-mono);margin-top:5px}.mobile-menu-btn{display:none}.toast{position:fixed;bottom:24px;left:50%;transform:translateX(-50%);padding:12px 18px;background:var(--text-strong);color:var(--surface);border-radius:8px;box-shadow:var(--shadow-lg);z-index:150;max-width:calc(100vw - 32px);font-size:13px}.toast.error{background:var(--danger);color:white}.command-results{display:grid;gap:4px;margin-top:16px}.command-results button{display:flex;align-items:center;justify-content:space-between;text-align:left;padding:12px;border-radius:5px;color:var(--text);gap:20px}.command-results button:hover{background:var(--accent-soft)}.command-results small{color:var(--muted);font-size:12px}.command-results .eyebrow{margin:14px 10px 4px}.confirm-message{font-size:14px;line-height:1.8}.skip-link{position:fixed;top:8px;left:50%;z-index:200;background:var(--surface);padding:10px;transform:translateY(-200%)}.skip-link:focus{transform:translateY(0)}.nav-backdrop{position:fixed;inset:0;background:#10202060;z-index:40}
@media(max-width:1100px){.search-trigger{width:36px;padding:0;justify-content:center}.search-trigger span,.search-trigger kbd{display:none}.topbar{padding:0 20px}.content-scroll{padding:24px 20px}}
@media(max-width:800px){.app-shell,.nav-collapsed{grid-template-columns:1fr;--sidebar-width:240px}.sidebar{position:fixed;inset:0 auto 0 0;width:260px;transform:translateX(-105%);transition:transform .2s}.sidebar.open{transform:translateX(0)}.nav-collapsed .brand-copy,.nav-collapsed .nav-item span,.nav-collapsed .side-account div,.nav-collapsed .nav-caption{display:block}.nav-collapsed .nav-item{justify-content:start;padding:0 14px}.collapse-btn{display:none}.mobile-menu-btn{display:inline-flex}.topbar{flex-wrap:wrap;justify-content:start;padding:10px 16px;gap:12px;position:relative}.breadcrumb{flex:1}.top-actions{display:contents}.group-select{order:2;width:100%;max-width:none;margin-top:2px}.search-trigger{display:none}.workspace-tabs{gap:24px;padding:0 16px}.content-scroll{padding:20px 16px 28px}.context-label{display:none}.page-heading{margin-bottom:20px}.page-heading h1{font-size:24px}.workspace-tabs a{padding-top:14px}.command-results button{align-items:start;flex-direction:column;gap:5px}}
</style>
